91	        final meta = json['meta'] as Map<String, dynamic>;
92	        final nextCursor = meta['nextCursor'] as String?;
93	        return right((items: items, nextCursor: nextCursor));
94	      } catch (error) {
95	        // Same client-side-parse-failure rationale as `create()` above.
96	        return left(Failure.malformedResponse(message: error.toString()));
97	      }
98	    });
99	  }
100	
101	  /// Calls `entries-get` (`ApiClient.get`) with [id] appended as the one
102	  /// trailing path segment (Conventions: "path parameters appended as
103	  /// trailing segments") — decodes the response's own `data` object exactly
104	  /// as [create]/[list] already do, a superset [EntryDto] already handles
105	  /// (Boundaries: "its response is a superset, same as create/list's DTO
106	  /// reuse").
107	  Future<Either<Failure, EntryDto>> get(String id) async {
108	    final result = await _apiClient.get('entries-get', pathParams: [id]);
109	    return result.flatMap((json) {
110	      try {
111	        final data = json['data'] as Map<String, dynamic>;
112	        return right(EntryDto.fromJson(data));
113	      } catch (error) {
114	        // Same client-side-parse-failure rationale as `create()`/`list()`
115	        // above.
116	        return left(Failure.malformedResponse(message: error.toString()));
117	      }
118	    });
119	  }
120	
121	  /// spec-5-1 — calls `entries-search` (`ApiClient.get`) with exactly one
122	  /// query parameter, `q` — [query] is this method's own non-optional
123	  /// positional parameter (Boundaries: no `limit`/`cursor`); the backend's
124	  /// own contract (`openapi.yaml`) marks `q` itself as optional, this
125	  /// client just always supplies it. The response's `data` array decodes
126	  /// with the exact same `EntryDto.
127	  /// fromJson` [list] already uses — a superset response (`similarity`/
128	  /// `mode` fields the Code Map names) is simply ignored by
129	  /// `json_serializable`'s generated `fromJson`, same convention [get]'s
130	  /// own superset-response doc already gives.
131	  ///
132	  /// spec-5-3 — [source]/[dateFrom]/[dateTo] are sent only when non-null,
133	  /// mirroring [list]'s own convention exactly: [source] as its own
134	  /// `.name`, [dateFrom]/[dateTo] as `.toUtc().toIso8601String()` (same
135	  /// RFC3339 rationale [list]'s own doc already gives).
136	  Future<Either<Failure, List<EntryDto>>> search(
137	    String query, {
138	    EntrySource? source,
139	    DateTime? dateFrom,
140	    DateTime? dateTo,
141	  }) async {
142	    final result = await _apiClient.get(
143	      'entries-search',
144	      queryParameters: {
145	        'q': query,
146	        'source': ?source?.name,
147	        'dateFrom': ?dateFrom?.toUtc().toIso8601String(),
148	        'dateTo': ?dateTo?.toUtc().toIso8601String(),
149	      },
150	    );
151	    return result.flatMap((json) {
152	      try {
153	        final data = json['data'] as List<dynamic>;
154	        final items = data
155	            .map((item) => EntryDto.fromJson(item as Map<String, dynamic>))
156	            .toList();
157	        return right(items);
158	      } catch (error) {
159	        // Same client-side-parse-failure rationale as `create()`/`list()`/
160	        // `get()` above.
161	        return left(Failure.malformedResponse(message: error.toString()));
162	      }
163	    });
164	  }
165	}
