188	  /// spec-7-1 — the header's download icon: opens a free-form period
189	  /// picker (Design Notes: `showDateRangePicker`, docs/input silent on
190	  /// the widget), then creates the export job (`ExportJobCubit.start()`).
191	  /// A create failure never opens the sheet (Boundaries) — an inline
192	  /// `SnackBar` with the mapped `Failure.message` instead, and the
193	  /// one-shot cubit is closed immediately rather than left to
194	  /// `ExportStatusSheet.show()`'s own disposal (which never runs, since
195	  /// the sheet itself never opens on this path). spec-7-3's one
196	  /// exception: an `EXPORT_EMPTY_PERIOD` create failure makes
197	  /// `ExportJobCubit.start()` return `true` instead, so it falls through
198	  /// to the same `ExportStatusSheet.show()` call below and opens
199	  /// directly on "Período vazio".
200	  Future<void> _onExportTap() async {
201	    if (_exportInFlight) {
202	      return;
203	    }
204	    _exportInFlight = true;
205	    try {
206	      final now = DateTime.now();
207	      final range = await showDateRangePicker(
208	        context: context,
209	        firstDate: DateTime(2000),
210	        lastDate: now,
211	        initialDateRange: DateTimeRange(
212	          start: now.subtract(const Duration(days: 30)),
213	          end: now,
214	        ),
215	      );
216	      if (range == null || !mounted) {
217	        return;
218	      }
219	      final exportCubit = sl<ExportJobCubit>();
220	      final started = await exportCubit.start(
221	        periodStart: range.start,
222	        periodEnd: range.end,
223	      );
224	      if (!mounted) {
225	        await exportCubit.close();
226	        return;
227	      }
228	      if (!started) {
229	        final message = switch (exportCubit.state) {
230	          ExportJobError(failure: final failure) => failure.message,
231	          _ => 'Não foi possível solicitar a exportação.',
232	        };
233	        await exportCubit.close();
234	        if (!mounted) {
235	          return;
236	        }
237	        ScaffoldMessenger.of(context)
238	            .showSnackBar(SnackBar(content: Text(message)));
239	        return;
240	      }
241	      await ExportStatusSheet.show(context, cubit: exportCubit);
242	    } finally {
243	      _exportInFlight = false;
244	    }
245	  }
