766	
767	  @override
768	  Widget build(BuildContext context) {
769	    final source = cubit.activeSource;
770	    final dateFrom = cubit.activeDateFrom;
771	    final dateTo = cubit.activeDateTo;
772	    final dateRangePreset = cubit.activeDateRangePreset;
773	    final hasDateRange = dateFrom != null && dateTo != null;
774	    return Padding(
775	      padding: const EdgeInsets.fromLTRB(
776	        DesignTokens.spacingMd,
777	        DesignTokens.spacingSm,
778	        DesignTokens.spacingMd,
779	        0,
780	      ),
