785	        children: [
786	          if (source != null)
787	            _ActiveFilterChip(
788	              label: entrySourceLabel(source),
789	              // I/O matrix: "Remove one of two active chips" — re-applies
790	              // every *other* active filter exactly as it stood, dropping
791	              // only this one. Round-2 review fix: passes `dateRangePreset`
792	              // back in too — otherwise the still-active date range would
793	              // revert to the cubit's default "Todo o período" preset.
794	              onRemove: () {
