816	            onTap: () {
817	              // I/O matrix: "Clear all filters" — restores the full
818	              // unfiltered list in place, no reload/re-mount (Boundaries).
819	              cubit.clearFilters();
820	              searchCubit.updateFilters();
821	            },
822	            child: Text(
823	              'Limpar filtros',
824	              style: DesignTokens.textMonoCaption.copyWith(
